		var typed any
		switch kind {
		case filterx.KindInt:
			if n, ok := v.(json.Number); ok {
				if i, err := n.Int64(); err == nil {
					typed = i
				} else if f, err := n.Float64(); err == nil && f == float64(int64(f)) {
					typed = int64(f)
				}
			}
		case filterx.KindFloat:
			if n, ok := v.(json.Number); ok {
				if f, err := n.Float64(); err == nil {
					typed = f
				}
			}
		case filterx.KindBool:
			if b, ok := v.(bool); ok {
				typed = b
			}
		case filterx.KindDate:
			if s, ok := v.(string); ok {
				if _, err := filterx.ParseDate(s); err == nil {
					typed = s
				}
			}
		case filterx.KindTimestamp:
			if s, ok := v.(string); ok {
				if _, err := filterx.ParseTimestamp(s); err == nil {
					typed = s
				}
			}
		default:
			if s, ok := v.(string); ok {
				typed = s
			}
		}
		if typed != nil {
			setPath(out, strings.Split(path, "."), typed)
		}
